{"cards": [{"node_code": "N_b1ff40408791ba6d", "definition": "定义材料选用前的输入条件，包括服役载荷、环境、寿命要求，以及具体的性能指标、可制造性、成本与可持续性约束。", "boundary": "聚焦于“需求侧”的定义与量化，即确定材料必须满足什么条件。涵盖从工程功能需求到具体材料性能参数的转化过程，以及非性能约束（如成本、环保）的设定。不涉及具体的材料筛选算法或材料本身的微观机理研究。", "includes": ["载荷、环境、寿命等服役条件分析与需求定义", "关键材料性能指标（强度、韧性等）的确定与约束设定", "可制造性、成本效益及可持续性（绿色设计）指标评估"], "excludes": ["具体的材料筛选方法、数据库查询或多属性决策算法", "材料微观结构演变机理或基础物理性能测试方法"], "sibling_distinctions": [{"other_code": "N_beaff811194471a0", "rule": "本节点关注“需要什么”（需求定义与指标设定），兄弟节点关注“选什么”（基于需求的筛选与决策）；涉及性能数据时，侧重作为约束条件归本节点，侧重作为筛选依据归兄弟节点。"}, {"other_code": "N_06dd41e78e33d6f3", "rule": "本节点关注现有材料体系下的需求匹配，兄弟节点关注通过设计创造新材料或新结构以满足需求；涉及性能目标时，侧重作为选型输入归本节点，侧重作为设计目标归兄弟节点。"}], "cross_boundary_rule": "涉及性能指标时，若侧重指标的定义、来源及约束条件归本节点，若侧重指标的计算模型或微观机理归材料结构性能节点；涉及成本时，若侧重作为选型约束归本节点，若侧重制造工艺成本优化归制造节点。"}, {"node_code": "N_beaff811194471a0", "definition": "研究基于既定需求与指标，利用数据库、筛选图及多属性决策方法从现有材料库中优选材料，并评估替代方案的风险与兼容性。", "boundary": "聚焦于“决策侧”的过程与方法，即在已知需求下如何从候选材料中做出选择。涵盖材料信息检索、筛选逻辑、权衡分析以及材料替换时的工程风险评估。不涉及材料本身的微观设计或新成分开发。", "includes": ["材料数据库应用、筛选图（Ashby图）及信息检索方法", "多属性决策（MCDM）、加权评分及性能-成本权衡分析", "材料替代策略、相容性分析、供应链风险及失效风险评估"], "excludes": ["材料需求的具体定义与性能指标设定（归材料需求与性能指标）", "通过改变成分或工艺开发全新材料体系（归材料设计与集成设计）"], "sibling_distinctions": [{"other_code": "N_b1ff40408791ba6d", "rule": "本节点关注“怎么选”（筛选与决策），兄弟节点关注“选什么标准”（需求与指标）；涉及性能数据时，侧重作为筛选变量归本节点，侧重作为约束定义归兄弟节点。"}, {"other_code": "N_06dd41e78e33d6f3", "rule": "本节点关注在现有材料库中“挑选”，兄弟节点关注“创造”或“定制”材料；涉及新材料时，侧重评估其作为替代品的可行性归本节点，侧重其成分工艺设计归兄弟节点。"}], "cross_boundary_rule": "涉及材料替代时，若侧重替代后的性能验证与风险评估归本节点，若侧重替代材料的微观改性归材料结构性能节点；涉及数据库时，若侧重数据用于决策归本节点，若侧重数据本身的生成与表征归材料表征节点。"}, {"node_code": "N_06dd41e78e33d6f3", "definition": "研究通过调控成分、工艺、组织与性能的协同关系来设计新材料，以及材料、结构与制造工艺的集成协同设计方法。", "boundary": "聚焦于“创造侧”与“系统侧”的设计，即如何开发满足特定需求的新材料或优化材料-结构-制造系统。涵盖计算材料学、数据驱动设计、逆向设计以及跨学科的系统集成。不涉及现有材料的简单筛选或基础需求定义。", "includes": ["成分-工艺-组织-性能（CPSP）关联建模与逆向设计", "计算材料学、机器学习/数据驱动的材料发现与设计", "材料-结构-制造协同设计、功能梯度材料及多尺度集成设计"], "excludes": ["现有标准材料的筛选与多属性决策（归材料选择与替代）", "材料基础分类、微观机理纯理论研究或纯性能测试（归材料结构性能）"], "sibling_distinctions": [{"other_code": "N_b1ff40408791ba6d", "rule": "本节点关注“怎么造/怎么设计”（材料开发），兄弟节点关注“需要什么”（需求定义）；涉及性能目标时，侧重作为设计输入归兄弟节点，侧重作为设计优化目标归本节点。"}, {"other_code": "N_beaff811194471a0", "rule": "本节点关注“创造”新材料或新体系，兄弟节点关注“挑选”现有材料；涉及新材料时，侧重其设计流程与算法归本节点，侧重其作为候选项的评估归兄弟节点。"}], "cross_boundary_rule": "涉及计算设计时，若侧重算法模型与材料发现归本节点，若侧重模型验证实验归材料表征节点；涉及结构优化时，若侧重材料属性对结构的影响归本节点，若侧重纯几何拓扑优化归力学/设计节点。"}]}
